diff --git a/apps/web/src/greeter.js b/apps/web/src/greeter.js
index 2165c46..790db20 100644
--- a/apps/web/src/greeter.js
+++ b/apps/web/src/greeter.js
@@ -1,4 +1,4 @@
 function greet(name) {
