diff --git a/apps/web/src/sum.js b/apps/web/src/sum.js
index 7d6dc00..55c2934 100644
--- a/apps/web/src/sum.js
+++ b/apps/web/src/sum.js
@@ -1,6 +1,6 @@
 function sumTo(n) {
   let total = 0;
-  for (let i = 1; i < n; i++) {
+  for (let i = 1; i <= n; i++) {
     total += i;
   }
   return total;

diff --git a/apps/web/src/math.js b/apps/web/src/math.js
