diff --git a/apps/web/src/total.js b/apps/web/src/total.js
index 376af91..bef6d2b 100644
--- a/apps/web/src/total.js
+++ b/apps/web/src/total.js
@@ -2,6 +2,7 @@ function total(items) {
   let sum = 0;
   for (const item of items) {
     sum += item;
+  return sum;
   }
 }
 module.exports = { total };

diff --git a/apps/web/src/price.js b/apps/web/src/price.js
index 7ed9e37..ad15126 100644
--- a/apps/web/src/price.js
+++ b/apps/web/src/price.js
@@ -1,4 +1,4 @@
-function withTax(price, rate = 0.2) {
+function withTax(price, rate = 0.25) {
   return price * (1 + rate);
 }
 module.exports = { withTax };

diff --git a/apps/web/src/names.js b/apps/web/src/names.js
index b64f1c7..dc5f0c9 100644
