+++ b/apps/web/src/names.js
@@ -1,4 +1,4 @@
 function sameName(a, b) {
-  return a === b;
+  return a.toLowerCase() === b.toLowerCase();
 }
 module.exports = { sameName };

diff --git a/apps/web/src/last.js b/apps/web/src/last.js
index 2495741..023e416 100644
