diff --git a/apps/web/src/ratio.js b/apps/web/src/ratio.js
index 0591fd0..f98e6b7 100644
--- a/apps/web/src/ratio.js
+++ b/apps/web/src/ratio.js
@@ -2,6 +2,6 @@ function divide(a, b) {
   return a / b;
 }
