diff --git a/apps/web/src/strings.js b/apps/web/src/strings.js
index dfe1404..7056cc3 100644
--- a/apps/web/src/strings.js
+++ b/apps/web/src/strings.js
@@ -1,5 +1,5 @@
 function capitalize(s) {
-  return s[0].toUpperCase() + s.slice(2);
