+  return Math.round(dollars * 100);
 }
 module.exports = { toCents };

diff --git a/apps/web/src/avg.js b/apps/web/src/avg.js
index c2ae92f..a2a8c8f 100644
--- a/apps/web/src/avg.js
+++ b/apps/web/src/avg.js
@@ -3,6 +3,7 @@ function average(xs) {
   for (const x of xs) {
     sum += x;
   }
+  if (xs.length === 0) return 0;
   return sum / xs.length;
 }
 module.exports = { average };

